// WF-1 Batch In — the second entry point, and the ONLY thing it does is decide item SHAPE.
//
// ============================================================================================
// THE SHAPE DECISION: one n8n item per lead. Not one item carrying an array of leads.
// ============================================================================================
// This is forced by the nodes that already exist downstream — read them before changing it:
//   * `Normalize Lead` is `runOnceForAllItems` and does `$input.all().map(...)`. It maps ITEMS.
//     It has no idea what a `.leads` array is. Hand it one item holding 25 leads and it returns
//     one normalized lead built from the envelope's own (absent) fields — lead_id '', gate skip
//     `no_identifier`, 24 people silently gone. Nothing errors. That is the bug that looks like
//     it works.
//   * `Reoon Verify (power)` interpolates `{{ $json.email }}` per item — one HTTP call per item.
//     One item = one verification, no matter how many leads are nested inside it.
//   * `Verify this lead?` (IF) routes PER ITEM. An array on one item is one routing decision for
//     the whole batch, so a single suppressed lead would drag 24 clean ones into `Skipped` — or,
//     worse, 24 suppressed ones through the gate behind one clean lead.
//   * `Gate`, `Classify`, `Shape Lead Row`, `Shape Reoon Event` are all `$input.all().map(...)`.
//   * The two Sheets READS are `executeOnce: true`, so N items still cost exactly one read of
//     `Leads` and one of `Suppression` — the batch does not multiply the Sheets calls.
// So the whole pipeline from `Normalize Lead` rightwards is ALREADY a batch pipeline. It was only
// ever fed one item because the manual path's Set node emits one. Nothing downstream changes.
//
// ============================================================================================
// WHAT A PARENT MAY SEND (arrival shape is tolerant; internal shape is not)
// ============================================================================================
// `VIO-source-leads` ends on a Report node that emits ONE item shaped
// `{ ok, source_config, product, ..., leads: [ {...}, {...} ] }` — an envelope with an array.
// An Execute Workflow node passes that item through untouched. So the envelope form has to be
// accepted, and un-nested here, once, at the boundary. Accepted forms:
//   1. one item with a leads array   -> `{ leads: [...] }` (also `items`/`batch`/`rows`/`people`)
//   2. N items, one lead each        -> passed straight through
//   3. a mix of 1 and 2, or several envelopes
//   4. an envelope wrapped one level in `body` (a parent that forwarded a webhook payload raw)
//   5. a leads array that arrived JSON-stringified
// The trigger is `inputSource: passthrough` on purpose: declaring a `workflowInputs` schema makes
// n8n DROP every field not in the schema, so `company_domain` / `linkedin_url` / `signal` would
// vanish on their way in and the personalized page would quietly lose its inputs.
//
// ============================================================================================
// FAILURE POSTURE: skip the bad entry, never abort the batch
// ============================================================================================
// Every entry is read inside its own try/catch and a non-object entry is skipped with a reason.
// One malformed lead out of 25 must not cost the other 24 their run. Nothing here throws:
// an empty or entirely-malformed batch returns zero items, downstream never executes, zero
// credits are spent, and the reason is on `_batch.warnings` in the execution record.
//
// This node does NOT gate, dedupe, suppress, verify, or normalise identifiers. Those live in
// `Normalize Lead` and `Gate (dedupe + suppression)`, in ONE copy, on the far side of the join —
// which is why both entry points converge here rather than each getting their own gate chain.

const MAX_BATCH = 250;

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

// Keys a parent might use for "here is the list". `leads` is what VIO-source-leads emits.
const LEAD_KEYS = ['leads', 'items', 'batch', 'rows', 'people'];

// Envelope-level values a lead may inherit when it does not carry its own. Deliberately a short
// explicit list: blanket-merging the envelope would splatter `ok` / `note` / `returned_by_apollo`
// onto every lead, and a reader could not tell a real field from batch bookkeeping.
const INHERIT = ['source_config', 'signal'];

// A lead has to look like a lead. Without this, an envelope with no recognisable list (a status
// object, say) would be treated as one lead, and the gate would file it as `no_identifier`.
// Identity-less but lead-SHAPED items are still passed through on purpose, so that the single
// "this has no stable key" ruling stays in the gate rather than being made twice in two places.
const LEADISH = ['email', 'contact_email', 'apollo_id', 'first_name', 'last_name',
                 'company', 'company_domain', 'linkedin_url', 'title', 'phone'];

// A list may arrive as a real array or as a JSON string. Parse defensively; return null (not a
// throw) for anything that is not a usable list.
function asArray(v) {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string') {
    const s = v.trim();
    if (!s || (s[0] !== '[' && s[0] !== '{')) return null;
    try {
      const p = JSON.parse(s);
      if (Array.isArray(p)) return p;
      return isObj(p) ? [p] : null;
    } catch (e) { return null; }
  }
  return null;
}

const collected = [];
const warnings = [];
let envelopes = 0;
let bare = 0;

for (const item of $input.all()) {
  let env = null;
  try { env = item.json; } catch (e) { env = null; }
  if (!isObj(env)) { warnings.push('input item is not an object - ignored'); continue; }

  // Unwrap at most ONE `body` layer, and only when the inner object is the one holding the list.
  const src = (isObj(env.body) && LEAD_KEYS.some((k) => k in env.body)) ? env.body : env;

  let arr = null;
  for (const k of LEAD_KEYS) {
    if (!(k in src)) continue;
    const a = asArray(src[k]);
    if (a) { arr = a; break; }
    if (src[k] !== null && src[k] !== undefined) {
      warnings.push("'" + k + "' is present but is not a list - ignored");
    }
  }

  if (arr) {
    envelopes++;
    const defaults = {};
    for (const f of INHERIT) {
      if (typeof src[f] === 'string' && src[f]) defaults[f] = src[f];
    }
    for (const raw of arr) {
      try {
        if (!isObj(raw)) { warnings.push('batch entry is not an object - skipped'); continue; }
        collected.push(Object.assign({}, defaults, raw));
      } catch (e) {
        warnings.push('batch entry could not be read - skipped: ' + (e && e.message));
      }
    }
    continue;
  }

  // No list on this item: treat it as a single lead, but only if it looks like one.
  try {
    if (LEADISH.some((k) => k in src)) { collected.push(Object.assign({}, src)); bare++; }
    else warnings.push('input item carries no lead list and no lead fields - ignored');
  } catch (e) {
    warnings.push('input item could not be read - skipped: ' + (e && e.message));
  }
}

// Hard cap. Every surviving lead can cost one Reoon credit, so an unbounded batch is an unbounded
// spend. Truncating (and saying so) is chosen over refusing: refusing would drop the whole batch
// on the floor, which is the more expensive mistake. `dropped_over_cap` is non-zero and visible
// on every item in the execution record, so a truncation is never silent.
const capped = collected.length > MAX_BATCH;
const leads = capped ? collected.slice(0, MAX_BATCH) : collected;

// Zero leads returns zero items. n8n then simply does not execute anything downstream: no Sheets
// read, no Reoon call, no row written, no error. An empty batch is a no-op, not a failure.
const meta = {
  entry: 'execute_workflow',
  envelopes: envelopes,
  bare_items: bare,
  received: collected.length,
  size: leads.length,
  capped: capped,
  dropped_over_cap: collected.length - leads.length,
  max_batch: MAX_BATCH,
  warnings: warnings,
  fanned_out_at: new Date().toISOString()
};

return leads.map((lead, i) => ({
  json: Object.assign({}, lead, { _batch: Object.assign({ index: i }, meta) })
}));

// WF-1 Normalize Lead — decide this lead's identity once, before anything is spent on it.
//
// lead_id rule (fixed — every later workflow recomputes it to find this row again):
//   the Apollo person id when the lead has one, otherwise the first 16 hex chars of
//   sha256(lowercased, trimmed email). Deterministic, collision-free at pilot scale, and it needs
//   no lookup against the Sheet.

// ---- sha256, inline ----------------------------------------------------------------------
// Implemented here rather than via require('crypto') because n8n's Code sandbox only exposes
// node builtins when NODE_FUNCTION_ALLOW_BUILTIN is set on the host. lead_id is the key every
// later workflow updates this row against, so it must not depend on a host env flag.
function sha256hex(msg) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const rr = (v, n) => ((v >>> n) | (v << (32 - n))) >>> 0;
  const bytes = [];
  for (let i = 0; i < msg.length; i++) {
    let c = msg.charCodeAt(i);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0xd800 || c >= 0xe000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else {
      i++;
      const cp = 0x10000 + (((c & 0x3ff) << 10) | (msg.charCodeAt(i) & 0x3ff));
      bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    }
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000), lo = bitLen >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255,
             (lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const w = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let i = 0; i < 16; i++) {
      w[i] = ((bytes[off + i * 4] << 24) | (bytes[off + i * 4 + 1] << 16) |
              (bytes[off + i * 4 + 2] << 8) | bytes[off + i * 4 + 3]) >>> 0;
    }
    for (let i = 16; i < 64; i++) {
      const s0 = (rr(w[i-15], 7) ^ rr(w[i-15], 18) ^ (w[i-15] >>> 3)) >>> 0;
      const s1 = (rr(w[i-2], 17) ^ rr(w[i-2], 19) ^ (w[i-2] >>> 10)) >>> 0;
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let i = 0; i < 64; i++) {
      const S1 = (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = (rr(a, 2) ^ rr(a, 13) ^ rr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H = [(H[0]+a)>>>0,(H[1]+b)>>>0,(H[2]+c)>>>0,(H[3]+d)>>>0,
         (H[4]+e)>>>0,(H[5]+f)>>>0,(H[6]+g)>>>0,(H[7]+h)>>>0];
  }
  return H.map(x => x.toString(16).padStart(8, '0')).join('');
}

// ---- identifier normalisation (must stay identical in every node that compares identifiers) ----
function normEmail(v) { return String(v == null ? '' : v).trim().toLowerCase(); }
function normDomain(v) {
  return String(v == null ? '' : v).trim().toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '')
    .replace(/[/?#].*$/, '');
}
function normLinkedIn(v) {
  let s = String(v == null ? '' : v).trim().toLowerCase();
  if (!s) return '';
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[?#].*$/, '').replace(/\/+$/, '');
  return s;
}
function normPhone(v) {
  // Compare on the last 10 digits so +1-202-555-0143, 12025550143 and (202) 555-0143 all match.
  // Lossy for some international numbers, but it errs toward MORE suppression matches, which is
  // the only safe direction for a compliance check.
  const d = String(v == null ? '' : v).replace(/\D/g, '');
  return d.length > 10 ? d.slice(-10) : d;
}
function emailDomain(email) {
  const e = normEmail(email);
  return e.indexOf('@') > -1 ? normDomain(e.split('@').pop()) : '';
}

return $input.all().map(item => {
  const l = item.json || {};
  const email = normEmail(l.email || l.contact_email);
  const apollo_id = String(l.apollo_id == null ? '' : l.apollo_id).trim();
  const lead_id = apollo_id || (email ? sha256hex(email).slice(0, 16) : '');
  const company_domain = normDomain(l.company_domain);
  const linkedin_url = normLinkedIn(l.linkedin_url);
  const phone = normPhone(l.phone);

  return { json: {
    lead_id: lead_id,
    lead_id_source: apollo_id ? 'apollo_id' : (email ? 'sha256(email)' : 'none'),
    source_config: String(l.source_config || ''),
    // Which product is pitching this lead. This node builds an EXPLICIT object rather than
    // spreading the input, so any field not named here is silently dropped — that is how
    // Product reached intake from VIO-inbox-mapper and vanished before the Leads row was
    // written (found live 2026-08-29, the row landed with a blank Product). Capital P matches
    // the live sheet column; lowercase is accepted because a caller may send either.
    Product: String(l.Product || l.product || ''),
    apollo_id: apollo_id,
    first_name: String(l.first_name || ''),
    last_name: String(l.last_name || ''),
    title: String(l.title || ''),
    company: String(l.company || ''),
    company_domain: company_domain,
    email: email,
    contact_email: email,
    phone: String(l.phone || ''),
    linkedin_url: String(l.linkedin_url || ''),
    timezone: String(l.timezone || ''),
    signal: String(l.signal || ''),
    has_email: email ? true : false,
    has_phone: phone ? true : false,
    // normalised comparison keys — the gate and nothing else reads these
    _ids: {
      email: email,
      email_domain: emailDomain(email),
      company_domain: company_domain,
      linkedin: linkedin_url,
      phone: phone
    }
  }};
});

// WF-1 Gate — decide whether this lead is worth spending a Reoon credit on.
//
// REWRITTEN 2026-09-05 for Supabase. It used to read the ENTIRE Leads tab and the ENTIRE
// Suppression tab into memory and match in JavaScript. Three things were wrong with that, and all
// three go away here rather than being ported:
//
//   1. Two implementations of suppression. The canonicalisation lived once in JavaScript and once
//      in SQL, and `test-suppression-parity.mjs` existed solely to prove they had not drifted.
//      Everyone on that list has asked us to stop, so a drift of one case is a person who opted out
//      and gets mailed anyway. Now there is one implementation — `is_suppressed()` — and the
//      question of parity cannot arise.
//   2. The dedupe compared `normEmail` output, which lowercases and trims but does NOT strip
//      zero-width characters. A pasted address carrying one read as a different person and was
//      verified again. The database compares `vio_canon()` on both sides, which does strip them, so
//      this is strictly stricter than what it replaces.
//   3. It scaled with the size of the sheet, not the size of the batch.
//
// What stays in JavaScript is the part that is genuinely about THIS batch and not about the
// database: two copies of the same person in one upload must not both be verified.
const leads = $('Normalize Lead').all().map((i) => i.json);
const answers = $input.all().map((i) => i.json || {});

// Postgres answered once per lead, in order. Falling back to a "worst case" answer rather than a
// permissive one: if the row is missing we cannot prove the person is not suppressed, and the only
// safe way to be wrong is to hold the lead rather than mail it.
const answerFor = (i) => answers[i] || { dupe: true, suppressed: true, _missing: true };

const batchEmail = new Set();
const batchId = new Set();

return leads.map((lead, i) => {
  const a = answerFor(i);
  const email = String(lead.email || '');
  let gate_action = 'verify';
  let gate_reason = 'ok';   // the established contract — callers and tests read this literal
  let gate_detail = '';

  if (!lead.lead_id) {
    gate_action = 'skip';
    gate_reason = 'no_identifier';
    gate_detail = 'lead has neither an apollo_id nor an email - no stable key, refusing to verify';
  } else if (a._missing) {
    gate_action = 'skip';
    gate_reason = 'gate_unavailable';
    gate_detail = 'the database did not answer for this lead - holding it rather than assuming it is safe to mail';
  } else if (a.suppressed === true) {
    gate_action = 'skip';
    gate_reason = 'suppressed';
    gate_detail = 'is_suppressed() matched on one of email / domain / phone / linkedin';
  } else if (a.dupe === true) {
    gate_action = 'skip';
    gate_reason = 'duplicate';
    gate_detail = 'already in leads (contact_email=' + email + ') - not re-verifying';
  } else if (batchEmail.has(email) || batchId.has(lead.lead_id)) {
    gate_action = 'skip';
    gate_reason = 'duplicate_in_batch';
    gate_detail = 'an earlier lead in THIS batch already claimed ' +
      (batchEmail.has(email) ? 'contact_email=' + email : 'lead_id=' + lead.lead_id) +
      ' - verifying the same person twice in one run would spend two credits';
  }

  // Only a lead that is actually going to be verified claims its identifiers, so a skipped
  // duplicate never blocks a later, cleaner copy of the same person from being the one that runs.
  if (gate_action === 'verify') {
    if (email) batchEmail.add(email);
    if (lead.lead_id) batchId.add(lead.lead_id);
  }

  return { json: Object.assign({}, lead, {
    gate_action,
    gate_reason,
    gate_detail,
    // Kept for the result node and for anyone reading an old execution: the numbers used to be
    // "how many rows did we scan". There is no scan any more, so they say so rather than lying
    // with a zero that reads like an empty sheet.
    leads_rows_scanned: null,
    suppression_rows_scanned: null,
    gate_source: 'supabase',
    gated_at: new Date().toISOString(),
  })};
});

// WF-1 Classify — map Reoon power-mode result to an action.
// Gate on `status`, per the live-tested Reoon behaviour in INTEGRATIONS.md:
//   safe/valid           -> pass
//   invalid/spamtrap     -> drop (SMTP-confirmed bad)
//   disposable           -> needs_review  (Reoon mis-flags greylisted corporate domains as
//                                          disposable - a false negative; a human confirms)
//   catch_all/unknown/role/anything else -> needs_review
// DO NOT "improve" this mapping. Auto-dropping on `disposable` silently loses good leads.
//
// The lead is recovered by email (Reoon echoes the address it verified) rather than by item index,
// because the gate's IF node removes skipped leads and indices no longer line up.
const gated = $('Gate (dedupe + suppression)').all();
const byEmail = {};
for (const g of gated) {
  const e = String((g.json || {}).email || '').toLowerCase();
  if (e) byEmail[e] = g.json;
}
let verified = [];
try { verified = $('Verify this lead?').all(0); } catch (e) { verified = []; }

return $input.all().map((item, i) => {
  const r = item.json || {};
  const lead = byEmail[String(r.email || '').toLowerCase()] ||
               ((verified[i] || {}).json) || {};
  const status = String(r.status || 'unknown').toLowerCase();
  const score = (r.overall_score !== undefined ? r.overall_score : null);
  let action, reason;
  if (['safe', 'valid'].includes(status)) {
    action = 'pass'; reason = 'deliverable, safe to send';
  } else if (['invalid', 'spamtrap'].includes(status)) {
    action = 'drop'; reason = 'hard fail: ' + status;
  } else if (status === 'disposable') {
    action = 'needs_review';
    reason = 'flagged disposable - confirm real throwaway vs greylisted corporate (known Reoon false-negative)';
  } else {
    action = 'needs_review'; reason = 'ambiguous (' + status + ') - human judges';
  }
  return { json: {
    lead_id: lead.lead_id || null,
    email: lead.email || r.email || null,
    name: [lead.first_name, lead.last_name].filter(Boolean).join(' ') || null,
    company: lead.company || null,
    reoon_status: status,
    overall_score: score,
    is_safe_to_send: (r.is_safe_to_send !== undefined ? r.is_safe_to_send : null),
    is_catch_all: (r.is_catch_all !== undefined ? r.is_catch_all : null),
    is_deliverable: (r.is_deliverable !== undefined ? r.is_deliverable : null),
    action: action,
    reason: reason,
    verified_at: new Date().toISOString(),
    lead: lead
  }};
});

// Shape the Events row for the Reoon call that just happened. Keys MUST equal Events column names.
//
// est_cost_usd is deliberately left blank: COSTS.md records Reoon's $/credit as [UNKNOWN] on
// purpose ("measure, don't estimate"), and a made-up number in the cost meter is worse than a gap.
// `units: 1` is the honest, meterable fact - one /verify call, one credit.
return $input.all().map(item => {
  const c = item.json || {};
  const l = c.lead || {};
  const detail = [c.reoon_status, (c.overall_score === null || c.overall_score === undefined)
    ? null : 'score ' + c.overall_score].filter(Boolean).join(', ');
  return { json: {
    timestamp: c.verified_at || new Date().toISOString(),
    lead_id: c.lead_id || '',
    lead_email: c.email || '',
    tool: 'reoon',
    action: 'verify',
    units: 1,
    est_cost_usd: '',
    result: c.action + (detail ? ' (' + detail + ')' : ''),
    workflow: 'VIO-intake-verify-curate',
    source_config: l.source_config || ''
  }};
});

// Shape the Leads row. Keys here MUST equal Leads column names exactly — the Sheets node runs in
// autoMapInputData mode and matches on the header text, so a typo silently drops a value.
// (`handlingExtraData: ignoreIt` on that node stops an unexpected key from adding a new column.)
//
// Columns this stage genuinely cannot know yet are written as empty strings rather than left out,
// so the row is full-width and later in-place updates line up.
return $input.all().map(item => {
  const c = item.json || {};
  const l = c.lead || {};
  const now = new Date().toISOString();
  return { json: {
    lead_id: c.lead_id || '',
    source_config: l.source_config || '',
    // Which product owns this lead. Capital P matches the live Leads column; the sheet is
    // authoritative over SHEET_SCHEMA.md, which still documents it lowercase. Separate from
    // source_config on purpose — that one records how the lead ARRIVED, not who pitches it.
    Product: l.Product || l.product || '',
    apollo_id: l.apollo_id || '',
    first_name: l.first_name || '',
    last_name: l.last_name || '',
    title: l.title || '',
    company: l.company || '',
    company_domain: l.company_domain || '',
    has_email: l.has_email === true,
    has_phone: l.has_phone === true,
    contact_email: c.email || '',
    phone: l.phone || '',
    linkedin_url: l.linkedin_url || '',
    timezone: l.timezone || '',
    signal: l.signal || '',
    opener: '',
    email_draft: '',
    reoon_status: c.reoon_status || '',
    verify_action: c.action || '',
    verify_reason: c.reason || '',
    sendr_page_id: '',
    sendr_page_url: '',
    gif_url: '',
    // The verdict decides the lifecycle state. This was hardcoded 'not_sent', which was harmless
    // only while nothing consumed it — as of 2026-08-29 'not_sent' is what VIO-demo-sheet-run
    // treats as READY, so an address Reoon had just rejected as undeliverable was being written
    // into Leads marked ready to send. Found live on the first end-to-end run.
    //   pass         -> not_sent      (verified, ready for the runner to claim)
    //   needs_review -> needs_review  (written, but a human should look before it sends)
    //   drop         -> dropped       (undeliverable; kept as a record, never sent)
    channel_state_email: c.action === 'drop' ? 'dropped'
                       : c.action === 'needs_review' ? 'needs_review'
                       : 'not_sent',
    channel_state_linkedin: 'not_sent',
    idempotency_key: '',
    reply_received: false,
    reply_sentiment: '',
    reply_out_of_office: false,
    // 4-value enum, never a boolean: not_eligible / pending_approval / called / skipped.
    // `pending_approval` is the legally-required human gate before any automated call (TCPA), so a
    // new lead starts at not_eligible and only a confirmed positive reply can ever move it.
    call_state: 'not_eligible',
    meeting_booked: false,
    created_at: now,
    updated_at: now
  }};
});

// Tell the CALLER what happened to each lead. Added 2026-08-29.
//
// Until now this workflow had no answer for its caller. It has four terminal branches — written,
// skipped as a duplicate, skipped as suppressed, Reoon call failed — and an Execute Workflow node
// returns whichever of them happened to run last. A caller could not tell "verified and written"
// from "silently dropped as suppressed", so VIO-inbox-mapper could not honestly report an outcome
// back onto the Inbox row a human is watching.
//
// This node is the single join. Every terminal branch feeds it, so it runs exactly once per
// execution and its output IS the sub-workflow's return value.
//
// It does NOT trust the items flowing into it — a Google Sheets node's output shape is its own
// business and has changed across versions. The verdicts are read straight from the two nodes
// that decide them, and identity is read from `Batch In`, which is the closest node to the
// caller's own input and the only one guaranteed to still carry whatever the caller sent.

const R = (v) => (typeof v === 'string' ? v : v == null ? '' : String(v));
const key = (e) => R(e).trim().toLowerCase();

// 1. Identity as the CALLER sent it. `inbox_row` is VIO-inbox-mapper's row number; any other
//    caller simply has none and the field stays null. Nothing here requires it.
const identity = new Map();
try {
  for (const it of $('Batch In (one item per lead)').all()) {
    const j = it.json || {};
    const k = key(j.email || j.contact_email);
    if (k && !identity.has(k)) {
      identity.set(k, {
        inbox_row: j.inbox_row === undefined ? null : j.inbox_row,
        source_config: R(j.source_config),
      });
    }
  }
} catch (e) { /* manual-trigger path: Batch In never ran */ }

// 2. Verdicts from the verification branch. Absent when every lead was gated out before Reoon.
const verdicts = new Map();
try {
  for (const it of $('Classify (pass / drop / needs_review)').all()) {
    const j = it.json || {};
    const k = key(j.email);
    if (!k) continue;
    verdicts.set(k, {
      outcome: R(j.action) || 'needs_review',
      reason: R(j.reason),
      reoon_status: R(j.reoon_status),
      lead_id: R(j.lead_id),
      verified: true,
    });
  }
} catch (e) { /* nothing reached Reoon in this execution */ }

// 3. Leads the gate stopped before Reoon. Only fills gaps — a lead that reached Classify has a
//    real verdict and must never be overwritten by its gate row.
try {
  for (const it of $('Gate (dedupe + suppression)').all()) {
    const j = it.json || {};
    const k = key(j.email);
    if (!k || verdicts.has(k)) continue;
    if (R(j.gate_action) === 'verify') {
      // Reached the gate cleanly but has no Classify verdict: the Reoon call failed. Reporting
      // this as a skip would be a lie — the lead is unprocessed and should be retried, not
      // written off.
      verdicts.set(k, { outcome: 'verify_failed', reason: 'Reoon call did not return a verdict',
                        reoon_status: '', lead_id: R(j.lead_id), verified: false });
    } else {
      verdicts.set(k, { outcome: 'skipped', reason: R(j.gate_reason) || 'gated',
                        reoon_status: '', lead_id: R(j.lead_id), verified: false });
    }
  }
} catch (e) { /* gate never ran: empty batch */ }

// 4. One item per lead the caller handed us, in the caller's own terms.
const out = [];
for (const [k, v] of verdicts) {
  const id = identity.get(k) || {};
  out.push({ json: {
    email: k,
    inbox_row: id.inbox_row === undefined ? null : id.inbox_row,
    source_config: id.source_config || '',
    outcome: v.outcome,              // pass | drop | needs_review | skipped | verify_failed
    reason: v.reason,
    reoon_status: v.reoon_status,
    lead_id: v.lead_id,
    verified: v.verified,
    written_to_leads: v.outcome === 'pass' || v.outcome === 'needs_review',
    returned_at: new Date().toISOString(),
  }});
}
return out;
